/* Skills tool: units and significant figures. Each item is generated by
   ApChemMath.units.generate (chem-tool-math.js) from a seed and rendered and
   graded by ApChemQuestions like any bank item: value, units and significant
   figures marked separately, with the targeted notes (J for kJ, °C for K,
   ln for log, the wrong R). Contexts are data (chem/data/tools/
   units-sig-figs.json) and unlock with their units. Answers are recorded as
   "units-sig-figs:<context>:<kind>". */
(function(){
  'use strict';
  var T = window.ApChemTools;
  if(!T) return;
  var KIND = { muldiv: 'Multiplying and dividing', addsub: 'Adding and subtracting', gas: 'Gas law: kelvin and R', rchoice: 'Which R?', calorimetry: 'Calorimetry: J, kJ and sign', pH: 'pH: decimal places' };
  T.mount('units-sig-figs', function(app, data){
    var M = window.ApChemMath, Q = window.ApChemQuestions, esc = T.esc;
    var ctxs = data.contexts, gid = T.nid('us'), only = '', seed = 0;
    app.insertAdjacentHTML('beforeend', '<div class="bt-intro">' + data.intro + '</div>' + T.box(data.howItWorksTitle, data.howItWorks) +
      '<div class="bt-controls cd-pick"></div><section class="bt-problem" aria-labelledby="' + gid + '-h"></section>');
    var area = app.querySelector('.bt-problem');
    var kinds = ctxs.map(function(c){ return c.kind; }).filter(function(k, i, a){ return a.indexOf(k) === i; });
    if(kinds.length > 1){
      var sel = T.choiceSelect({ label: 'Habit to practice', options: [{ value: '', label: 'Mixed: any habit' }].concat(kinds.map(function(k){ return { value: k, label: KIND[k] }; })), value: '', onChange: function(v){ only = v; draw(true, true); } });
      app.querySelector('.cd-pick').appendChild(sel.el);
    }
    function fresh(){ return 10000 + Math.floor(Math.random() * 89999); }
    try{ var m = /[?&#]seed=(\d+)/.exec(location.search + location.hash); seed = m ? +m[1] : fresh(); }catch(e){ seed = fresh(); }
    function draw(focus, renew){
      if(renew) seed = fresh();
      var r = M.rng(seed), pool = ctxs.filter(function(c){ return !only || c.kind === only; }), ctx = r.pick(pool.length ? pool : ctxs);
      var item = M.units.generate(r, Object.assign({ slug: 'units-sig-figs' }, ctx)).item;
      area.innerHTML = '<div class="bt-prob-head"><h2 id="' + gid + '-h" tabindex="-1">' + esc(KIND[ctx.kind]) + '</h2><p class="bt-code">Problem code <b>' + seed + '</b> <a href="?seed=' + seed + '">Link to this problem</a></p></div><div class="us-q"></div><div class="bt-next"></div>';
      T.questions(area.querySelector('.us-q'), [item], {}, 'units-sig-figs');
      area.querySelector('.us-q').addEventListener('chem:answered', function(){
        var nx = area.querySelector('.bt-next');
        nx.innerHTML = '<div class="bt-actions"><button type="button" class="btn-press sm us-again">New problem</button></div>';
        nx.querySelector('.us-again').addEventListener('click', function(){ draw(true, true); });
      });
      if(focus) area.querySelector('h2').focus();
    }
    draw(false);
  });
})();
